# 3s where each 2 would be if moved 1 step toward the 3 at (5,6)
output = [[0]*11 for _ in range(11)]

positions_2 = [
    (0, 10), (1, 1), (1, 6), (3, 1), (5, 3), (5, 8), (8, 0), (9, 1), (9, 10), (10, 6)
]

# Keep 3 at original position
output[5][6] = 3

for r, c in positions_2:
    # Move 1 step toward (5,6)
    rr, cc = 5, 6
    dr = r - rr  # where 2 is relative to 3
    dc = c - cc

    # Direction toward 3 (opposite)
    if dr != 0:
        step_r = -1 if dr > 0 else 1
    else:
        step_r = 0
    if dc != 0:
        step_c = -1 if dc > 0 else 1
    else:
        step_c = 0

    nr, nc = r + step_r, c + step_c
    if 0 <= nr < 11 and 0 <= nc < 11:
        output[nr][nc] = 3

